def format_wf(w):
    slug, name, title, cat, desc, steps, tools, faqs = w
    steps_str = ", ".join(f'"{s}"' for s in steps)
    tools_str = ", ".join(f'"{t}"' for t in tools)
    faq_str = ", ".join(f'{{ question: "{q}", answer: "{a}" }}' for q, a in faqs)
    return (
        f'  {{ slug: "{slug}", name: "{name}", title: "{title}", '
        f'category: "{cat}", description: "{desc}", '
        f'steps: [{steps_str}], '
        f'tools: [{tools_str}], '
        f'faq: [{faq_str}] }},'
    )

lines = ['import type { Workflow } from "@/types";', '', 'export const workflows: Workflow[] = [']
for w in WORKFLOWS:
    lines.append(format_wf(w))
lines.append('];')
lines.append('')

content = '\n'.join(lines)
with open('/Users/adda247/personal/shipsquad/shipsquad-front/src/data/workflows.ts', 'w') as f:
    f.write(content)
print(f"Written {len(WORKFLOWS)} workflows to workflows.ts ({len(content)} bytes)")
